import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const s="/assets/blocks-for-ha/grid/de/light.png",a="/assets/blocks-for-ha/grid/de/dark.png",l="/assets/blocks-for-ha/themes/de/dark.png",o="/assets/blocks-for-ha/themes/de/tritanopia.png",m=JSON.parse('{"title":"Themes und Zoom","description":"Gespeicherte Theme-Auswahl und zusätzlicher Einpassen-Knopf im Blockly-Editor.","frontmatter":{"title":"Themes und Zoom","description":"Gespeicherte Theme-Auswahl und zusätzlicher Einpassen-Knopf im Blockly-Editor."},"headers":[],"relativePath":"projects/blocks-for-ha/themes.md","filePath":"projects/blocks-for-ha/themes.md","lastUpdated":1792754181000}'),d={name:"projects/blocks-for-ha/themes.md"};function h(u,e,g,c,p,b){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="themes-und-zoom" tabindex="-1">Themes und Zoom <a class="header-anchor" href="#themes-und-zoom" aria-label="Permalink to &quot;Themes und Zoom&quot;">​</a></h1><h2 id="logik-und-objekte-seit-0-1-56" tabindex="-1">Logik und Objekte seit 0.1.56 <a class="header-anchor" href="#logik-und-objekte-seit-0-1-56" aria-label="Permalink to &quot;Logik und Objekte seit 0.1.56&quot;">​</a></h2><p>In Standard/Dark sind Logik-Blocks blau und Objekt-Blocks braun, jeweils mit lesbarer weißer Schrift. Modern und Tritanopia behalten ihre eigenen Paletten. <strong>Falls / sonst falls / sonst</strong> steht jetzt direkt in <strong>Logik</strong>: Das Zahnrad öffnet den Baukasten für weitere Zweige; weitere Zweige und Sonst werden dort hinzugefügt oder entfernt. Bedingungen und Aktionsketten werden als native HA-Verzweigung ausgegeben. Bestehende Projekte bleiben kompatibel.</p><h2 id="punktraster-seit-0-1-51" tabindex="-1">Punktraster seit 0.1.51 <a class="header-anchor" href="#punktraster-seit-0-1-51" aria-label="Permalink to &quot;Punktraster seit 0.1.51&quot;">​</a></h2><p>Die Arbeitsfläche zeigt ein gut sichtbares natives Blockly-Punktraster mit 25 Einheiten Abstand und Einrasten, angelehnt an <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/BlocklyEditor.tsx" target="_blank" rel="noreferrer">ioBrokers Blockly-Editor</a>. Hintergrund und Punkte folgen der App-Darstellung <strong>Hell / Dunkel / System</strong> sofort, einschließlich Änderungen der Systemeinstellung. Die Blockly-Auswahl legt weiterhin die Farben von Blocks und Menüs fest; die Arbeitsfläche folgt der App-Darstellung auch bei der Palette Dark.</p><p>Zoom und Verschieben bewegen das Raster mit der Arbeitsfläche. Einpassen verändert die Größe der Menü-Blocks nicht. Darstellung und Palette ändern weder Automation noch YAML.</p><p><img src="'+s+'" alt="Helles Punktraster"></p><p><img src="'+a+'" alt="Dunkles Punktraster"></p><p>Seit <strong>0.1.27</strong> erhalten UGSo-Blocks in Standard/Dark weiße Beschriftungen. Mittlere blaue und braune Flächen werden dafür etwas dunkler, mit mindestens <strong>4,5:1</strong> Kontrast. Bei originalen hellen Modern-/Tritanopia-Farben wird passend kontrastreiche dunkle Schrift verwendet. Eingabefelder bleiben separat lesbar. Die Blockbilder im Katalog sind für DE/EN/FR mit dieser Korrektur neu erzeugt.</p><p>Seit <strong>0.1.16</strong> enthält die Werkzeugleiste über der Arbeitsfläche eine <strong>Theme-Auswahl</strong>. Sie betrifft den Blockly-Bereich einschließlich Kategorien, Blockauswahl und Blocks. Die Blockly-Palette ist unabhängig von der App-Darstellung. Es bleiben 111 Blocktypen.</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Darstellung</th><th>Originalquelle</th></tr></thead><tbody><tr><td>UGSo Standard</td><td>Bisherige UGSo-Gruppenfarben, dunkles Menü und helle Blockauswahl</td><td>Eigene UGSo-Anpassung auf Blockly Classic</td></tr><tr><td>Dark</td><td>Dunkle Arbeitsfläche, dunkle Blockauswahl und davon abgesetztes Kategorienmenü</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-dark" target="_blank" rel="noreferrer">theme-dark</a></td></tr><tr><td>Modern</td><td>Originale Modern-Palette mit kräftigeren Rändern und UGSo-Erweiterungsgruppen</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-modern" target="_blank" rel="noreferrer">theme-modern</a></td></tr><tr><td>Tritanopia</td><td>Originalpalette für die Standardgruppen und zusätzliche Farben für HA-spezifische Gruppen</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-tritanopia" target="_blank" rel="noreferrer">theme-tritanopia</a></td></tr></tbody></table><p>Tritanopia ist für Menschen mit entsprechender Farbsehschwäche gedacht. Auch eigene UGSo-Blocks und Kategorien verwenden jetzt Theme-Stile statt fest gesetzter Farben. Helle Blocks erhalten dunkle Beschriftungen, dunkle Blocks helle; Eingabefelder bleiben separat lesbar. Die ausgewählte Kategorie hat unabhängig von der Palette einen dunklen Hintergrund mit heller Schrift. Kategorienamen und Blocktexte bleiben zur Orientierung sichtbar. Dies ist keine vollständige Barrierefreiheitszertifizierung.</p><p><img src="'+l+'" alt="Dark im UGSo-Editor"></p><p><img src="'+o+'" alt="Tritanopia im UGSo-Editor"></p><h2 id="wechseln-und-speichern" tabindex="-1">Wechseln und speichern <a class="header-anchor" href="#wechseln-und-speichern" aria-label="Permalink to &quot;Wechseln und speichern&quot;">​</a></h2><p>Das Theme wird direkt umgeschaltet, ohne die Arbeitsfläche neu aufzubauen. Blocks, Verbindungen, Anordnung und YAML bleiben erhalten. Die Auswahl wird getrennt vom Projekt in diesem Browser gespeichert und nach dem Neuladen wieder verwendet. Projektdateien und YAML übertragen diese Anzeigeeinstellung nicht auf andere Browser. Unbekannte Einstellungen fallen auf UGSo Standard zurück; bei gesperrtem Browser-Speicher funktioniert der Wechsel für die aktuelle Sitzung.</p><p>Der vorhandene <strong>Geras-Renderer</strong> bleibt für alle Themes aktiv, damit Anschlussgeometrie und Bedienung erhalten bleiben. Das originale Modern-Theme empfiehlt Zelos/Thrasos; hier wird seine Farb-/Randpalette mit Geras verwendet und geprüft. Ein Renderer-Wechsel ist keine zusätzliche Option dieser Version.</p><h2 id="alle-blocks-einpassen" tabindex="-1">Alle Blocks einpassen <a class="header-anchor" href="#alle-blocks-einpassen" aria-label="Permalink to &quot;Alle Blocks einpassen&quot;">​</a></h2><p>Das originale <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/zoom-to-fit" target="_blank" rel="noreferrer">zoom-to-fit</a> ergänzt das Vier-Pfeile-Symbol neben den Zoom-Reglern. Ein Klick passt die Blocks an die verfügbare Arbeitsfläche an. Der Knopf ist auch mit Tab erreichbar und per Enter/Leertaste bedienbar. Zoom verändert die Ansicht, nicht die Automation.</p><p>Seit <strong>0.1.40</strong> haben Blocks in allen Themes <strong>16-px-Schrift</strong>. Das Blockmenü bleibt fest bei <strong>100 Prozent</strong>: Einpassen, Mausrad und Zoomregler verändern nur den Arbeitsbereich. Startzoom 100 Prozent, Einpassen 85–120 Prozent, manueller Zoom 50–240 Prozent. Große Automationen bleiben verschiebbar; Einpassen verkleinert sie höchstens auf 85 Prozent, damit die Schrift lesbar bleibt. Geprüft in Full HD, 2560 px und HiDPI.</p><p>Alle vier zusätzlichen Originalplugins sind auf <strong>13.3.0</strong> festgelegt, mit Blockly <strong>13.3.0</strong> eingebunden und unter Apache-2.0 lizenziert. Die sechs bisherigen Originalplugins bleiben auf 13.2.0. Die Pakete werden lokal ausgeliefert; keine externen Theme-Dateien oder CDN-Abhängigkeit. Originalquellen und Lizenzhinweise stehen auch im <a href="./blocks">Blockkatalog</a>.</p><p>Geprüft: vier Themes, Schrift auf hellen Tritanopia-Blocks, unveränderte Projekt-/YAML-Ausgabe, gespeicherte Auswahl, unbekannte/gesperrte Speichereinstellungen, Einpassen und mobile Breite. Die HA-Ausführung wird durch diese Anzeigeänderung nicht verändert.</p><h2 id="app-darstellung-hell-dunkel-oder-system" tabindex="-1">App-Darstellung: Hell, Dunkel oder System <a class="header-anchor" href="#app-darstellung-hell-dunkel-oder-system" aria-label="Permalink to &quot;App-Darstellung: Hell, Dunkel oder System&quot;">​</a></h2><p>Seit <strong>0.1.22</strong> bietet <strong>Darstellung</strong> im Kopfbereich <strong>Hell</strong>, <strong>Dunkel</strong> und <strong>System</strong> für die gesamte umgebende App-Oberfläche: Kopfbereich, Panels, Formulare, YAML-Ausgabe, Dialoge, Entitätsauswahl und eigenen Block-/Template-Editor. Standard ist System; Änderungen der Betriebssystem-/Browser-Farbpräferenz werden sofort übernommen. Eine manuelle Auswahl überschreibt die Systemvorgabe. Die Einstellung wird lokal in diesem Browser gespeichert; bei gesperrtem Browser-Speicher funktioniert die Umschaltung weiterhin für die aktuelle Seite.</p><p>Die Blockly-Themes bleiben separat in der Werkzeugleiste wählbar, einschließlich Modern und Tritanopia. Darstellung verändert weder Blocks noch erzeugtes YAML oder Projekte. Das originale Built-with-Blockly-Badge wechselt automatisch zur passenden hellen/dunklen Variante.</p>',25)])])}const f=t(d,[["render",h]]);export{m as __pageData,f as default};
